const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define time range and geometries
    const startDate = '2016-08-01';
    const endDate = '2018-02-28';

    // Get country boundaries
    const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
    const cambodia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));
    const vietnam = countries.filter(ee.Filter.eq('ADM0_NAME', 'Viet Nam'));

    // 2. Load active fire data (MODIS Thermal Anomalies/Fire locations)
    const fires = ee.FeatureCollection('MODIS/006/MCD14DL')
        .filterDate(startDate, endDate);

    // Check if collection has data
    const firesCount = fires.size().getInfo();
    if (firesCount === 0) {
        console.log(`Total fires in period: ${firesCount}`);
        console.log("<answer>C1</answer>");
        return;
    }

    // 3. Count fires in each country
    const cambodiaFires = fires.filterBounds(cambodia);
    const vietnamFires = fires.filterBounds(vietnam);

    const cambodiaCount = cambodiaFires.size().getInfo();
    const vietnamCount = vietnamFires.size().getInfo();

    // Print concise evidence
    console.log(`Cambodia fires: ${cambodiaCount}`);
    console.log(`Vietnam fires: ${vietnamCount}`);
    console.log(`Period: ${startDate} to ${endDate}`);

    // 4. Validate and determine answer
    if (typeof cambodiaCount !== 'number' || typeof vietnamCount !== 'number' || 
        isNaN(cambodiaCount) || isNaN(vietnamCount)) {
        console.log("<answer>C3</answer>");
    } else if (cambodiaCount > vietnamCount) {
        console.log("<answer>A</answer>");
    } else {
        console.log("<answer>B</answer>");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
